import { Invoice } from '@getalby/lightning-tools';
import { Relay, Filter, Event, EventTemplate } from 'nostr-tools';

type NWCAuthorizationUrlOptions = {
    name?: string;
    icon?: string;
    requestMethods?: Nip47Method[];
    notificationTypes?: Nip47NotificationType[];
    returnTo?: string;
    expiresAt?: Date;
    maxAmount?: number;
    budgetRenewal?: "never" | "daily" | "weekly" | "monthly" | "yearly";
    isolated?: boolean;
    metadata?: unknown;
};
type WithDTag = {
    dTag: string;
};
type WithOptionalId = {
    id?: string;
};
type Nip47SingleMethod = "get_info" | "get_balance" | "get_budget" | "make_invoice" | "pay_invoice" | "pay_keysend" | "lookup_invoice" | "list_transactions" | "sign_message" | "create_connection" | "make_hold_invoice" | "settle_hold_invoice" | "cancel_hold_invoice";
type Nip47MultiMethod = "multi_pay_invoice" | "multi_pay_keysend";
type Nip47Method = Nip47SingleMethod | Nip47MultiMethod;
type Nip47Capability = Nip47Method | "notifications";
type BudgetRenewalPeriod = "daily" | "weekly" | "monthly" | "yearly" | "never";
type Nip47GetInfoResponse = {
    alias: string;
    color: string;
    pubkey: string;
    network: string;
    block_height: number;
    block_hash: string;
    methods: Nip47Method[];
    notifications?: Nip47NotificationType[];
    metadata?: unknown;
    lud16?: string;
};
type Nip47GetBudgetResponse = {
    used_budget: number;
    total_budget: number;
    renews_at?: number;
    renewal_period: BudgetRenewalPeriod;
} | {};
type Nip47GetBalanceResponse = {
    balance: number;
};
type Nip47PayResponse = {
    preimage: string;
    fees_paid: number;
};
type Nip47MultiPayInvoiceRequest = {
    invoices: (Nip47PayInvoiceRequest & WithOptionalId)[];
};
type Nip47MultiPayKeysendRequest = {
    keysends: (Nip47PayKeysendRequest & WithOptionalId)[];
};
type Nip47MultiPayInvoiceResponse = {
    invoices: ({
        invoice: Nip47PayInvoiceRequest;
    } & Nip47PayResponse & WithDTag)[];
    errors: [];
};
type Nip47MultiPayKeysendResponse = {
    keysends: ({
        keysend: Nip47PayKeysendRequest;
    } & Nip47PayResponse & WithDTag)[];
    errors: [];
};
interface Nip47ListTransactionsRequest {
    from?: number;
    until?: number;
    limit?: number;
    offset?: number;
    unpaid?: boolean;
    /**
     * NOTE: non-NIP-47 spec compliant
     */
    unpaid_outgoing?: boolean;
    /**
     * NOTE: non-NIP-47 spec compliant
     */
    unpaid_incoming?: boolean;
    type?: "incoming" | "outgoing";
}
type Nip47ListTransactionsResponse = {
    transactions: Nip47Transaction[];
    /**
     * NOTE: non-NIP-47 spec compliant
     */
    total_count: number;
};
type Nip47Transaction = {
    type: "incoming" | "outgoing";
    state: "settled" | "pending" | "failed" | "accepted";
    invoice: string;
    description: string;
    description_hash: string;
    preimage: string;
    payment_hash: string;
    amount: number;
    fees_paid: number;
    settled_at: number;
    created_at: number;
    expires_at: number;
    /**
     * NOTE: non-NIP-47 spec compliant
     */
    settle_deadline?: number;
    metadata?: Nip47TransactionMetadata;
};
type Nip47TransactionMetadata = {
    comment?: string;
    payer_data?: {
        email?: string;
        name?: string;
        pubkey?: string;
    };
    recipient_data?: {
        identifier?: string;
    };
    nostr?: {
        pubkey: string;
        tags: string[][];
    };
} & Record<string, unknown>;
type Nip47NotificationType = Nip47Notification["notification_type"];
type Nip47Notification = {
    notification_type: "payment_received";
    notification: Nip47Transaction;
} | {
    notification_type: "payment_sent";
    notification: Nip47Transaction;
} | {
    notification_type: "hold_invoice_accepted";
    notification: Nip47Transaction;
};
type Nip47PayInvoiceRequest = {
    invoice: string;
    metadata?: Nip47TransactionMetadata;
    amount?: number;
};
type Nip47PayKeysendRequest = {
    amount: number;
    pubkey: string;
    preimage?: string;
    tlv_records?: {
        type: number;
        value: string;
    }[];
};
type Nip47MakeInvoiceRequest = {
    amount: number;
    description?: string;
    description_hash?: string;
    expiry?: number;
    metadata?: Nip47TransactionMetadata;
};
type Nip47MakeHoldInvoiceRequest = Nip47MakeInvoiceRequest & {
    payment_hash: string;
};
type Nip47SettleHoldInvoiceRequest = {
    preimage: string;
};
type Nip47SettleHoldInvoiceResponse = {};
type Nip47CancelHoldInvoiceRequest = {
    payment_hash: string;
};
type Nip47CancelHoldInvoiceResponse = {};
type Nip47LookupInvoiceRequest = {
    payment_hash?: string;
    invoice?: string;
};
type Nip47SignMessageRequest = {
    message: string;
};
type Nip47CreateConnectionRequest = {
    pubkey: string;
    name: string;
    request_methods: Nip47Method[];
    notification_types?: Nip47NotificationType[];
    max_amount?: number;
    budget_renewal?: BudgetRenewalPeriod;
    expires_at?: number;
    isolated?: boolean;
    metadata?: unknown;
};
type Nip47CreateConnectionResponse = {
    wallet_pubkey: string;
};
type Nip47SignMessageResponse = {
    message: string;
    signature: string;
};

interface Logger {
    debug(...args: unknown[]): void;
}

type SubCloser = {
    close: (reason?: string) => void;
};
type SubscribeManyParams = {
    onevent?: (evt: Event) => void;
    onconnect?: (url: string) => void;
    ondisconnect?: (url: string, reason: string) => void;
    abort?: AbortSignal;
};
declare class ReconnectingPool {
    protected relays: Map<string, Relay>;
    enablePing: boolean | undefined;
    maxWaitForConnection: number;
    constructor();
    ensureRelay(url: string, params?: {
        connectionTimeout?: number;
        abort?: AbortSignal;
    }): Promise<Relay>;
    close(relays: string[]): void;
    subscribe(relays: string[], filter: Filter, params: SubscribeManyParams): SubCloser;
    publish(relays: string[], event: Event, params?: {
        abort?: AbortSignal;
    }): Promise<string>[];
    listConnectionStatus(): Map<string, boolean>;
    destroy(): void;
}

interface NWCOptions {
    relayUrls: string[];
    walletPubkey: string;
    secret?: string;
    lud16?: string;
}
type NewNWCClientOptions = {
    relayUrls?: string[];
    secret?: string;
    walletPubkey?: string;
    nostrWalletConnectUrl?: string;
    lud16?: string;
    logger?: Logger;
    requireSecret?: boolean;
};
declare class NWCClient {
    pool: ReconnectingPool;
    relayUrls: string[];
    secret: string | undefined;
    lud16: string | undefined;
    walletPubkey: string;
    options: NWCOptions;
    logger: Logger;
    private _encryptionType;
    static parseWalletConnectUrl(walletConnectUrl: string, requireSecret?: boolean): NWCOptions;
    constructor(options?: NewNWCClientOptions);
    get nostrWalletConnectUrl(): string;
    getNostrWalletConnectUrl(includeSecret?: boolean): string;
    get connected(): boolean;
    get publicKey(): string;
    get encryptionType(): string;
    getPublicKey(): Promise<string>;
    signEvent(event: EventTemplate): Promise<Event>;
    getEventHash(event: Event): string;
    close(): void;
    encrypt(pubkey: string, content: string): Promise<any>;
    decrypt(pubkey: string, content: string): Promise<string>;
    static getAuthorizationUrl(authorizationBasePath: string, options: NWCAuthorizationUrlOptions | undefined, pubkey: string): URL;
    /**
     * create a new client-initiated NWC connection via HTTP deeplink
     *
     * @param authorizationBasePath the deeplink path e.g. https://my.albyhub.com/apps/new
     * @param options configure the created app (e.g. the name, budget, expiration)
     * @param secret optionally pass a secret, otherwise one will be generated.
     */
    static fromAuthorizationUrl(authorizationBasePath: string, options?: NWCAuthorizationUrlOptions, secret?: string): Promise<NWCClient>;
    getWalletServiceInfo(): Promise<{
        encryptions: string[];
        capabilities: Nip47Capability[];
        notifications: Nip47NotificationType[];
    }>;
    getInfo(): Promise<Nip47GetInfoResponse>;
    getBudget(): Promise<Nip47GetBudgetResponse>;
    getBalance(): Promise<Nip47GetBalanceResponse>;
    payInvoice(request: Nip47PayInvoiceRequest): Promise<Nip47PayResponse>;
    payKeysend(request: Nip47PayKeysendRequest): Promise<Nip47PayResponse>;
    signMessage(request: Nip47SignMessageRequest): Promise<Nip47SignMessageResponse>;
    createConnection(request: Nip47CreateConnectionRequest): Promise<Nip47CreateConnectionResponse>;
    multiPayInvoice(request: Nip47MultiPayInvoiceRequest): Promise<Nip47MultiPayInvoiceResponse>;
    multiPayKeysend(request: Nip47MultiPayKeysendRequest): Promise<Nip47MultiPayKeysendResponse>;
    makeInvoice(request: Nip47MakeInvoiceRequest): Promise<Nip47Transaction>;
    makeHoldInvoice(request: Nip47MakeHoldInvoiceRequest): Promise<Nip47Transaction>;
    settleHoldInvoice(request: Nip47SettleHoldInvoiceRequest): Promise<Nip47SettleHoldInvoiceResponse>;
    cancelHoldInvoice(request: Nip47CancelHoldInvoiceRequest): Promise<Nip47CancelHoldInvoiceResponse>;
    lookupInvoice(request: Nip47LookupInvoiceRequest): Promise<Nip47Transaction>;
    listTransactions(request: Nip47ListTransactionsRequest): Promise<Nip47ListTransactionsResponse>;
    subscribeNotifications(onNotification: (notification: Nip47Notification) => void, notificationTypes?: Nip47NotificationType[]): Promise<() => void>;
    private executeNip47Request;
    /**
     * @deprecated
     * multi- methods were removed from NIP-47.
     */
    private executeMultiNip47Request;
    private _checkConnected;
    private _selectEncryptionType;
    private _findPreferredEncryptionType;
}

/**
 * A lightning invoice to be received by your wallet, along with utility functions,
 * such as checking if the invoice was paid and acting upon it.
 */
declare class ReceiveInvoice {
    readonly transaction: Nip47Transaction;
    readonly invoice: Invoice;
    private _nwcClient;
    private _unsubscribeFunc?;
    private _timeoutFunc?;
    private _timeoutId?;
    constructor(nwcClient: NWCClient, transaction: Nip47Transaction);
    /**
     * Setup an action once the invoice has been paid.
     *
     * @param callback this method will be fired once we register the invoice was paid, with information of the received payment.
     * @returns the current instance for method chaining e.g. add optional timeout
     */
    onPaid(callback: (receivedPayment: Nip47Transaction) => void): ReceiveInvoice;
    /**
     * Setup an action that happens if the invoice is not paid after a certain amount of time.
     *
     * @param seconds the number of seconds to wait for a payment
     * @param callback this method will be called once the timeout is elapsed.
     * @returns the current instance for method
     */
    onTimeout(seconds: number, callback: () => void): ReceiveInvoice;
    /**
     * Manually unsubscribe if you no longer expect the user to pay.
     *
     * This is only needed if no payment was received and no timeout was configured.
     */
    unsubscribe(): void;
    private _onPaidPollingFallback;
}

/**
 * An amount in satoshis
 */
type Amount = {
    satoshi: number;
} | {
    satoshi: Promise<number>;
};
declare const SATS: (amount: number) => Amount;
declare function resolveAmount(amount: Amount): Promise<{
    satoshi: number;
    millisat: number;
}>;

type LNClientCredentials = string | NWCClient | NewNWCClientOptions;
/**
 * A simple lightning network client to interact with your lightning wallet
 */
declare class LNClient {
    readonly nwcClient: NWCClient;
    /**
     * Create a new LNClient
     * @param credentials credentials to connect to a NWC-based wallet. This can be a NWC connection string e.g. nostr+walletconnect://... or an existing NWC Client. Learn more at https://nwc.dev
     */
    constructor(credentials: LNClientCredentials);
    /**
     * Make a payment
     * @param recipient a BOLT-11 invoice or lightning address
     * @param amount the amount to pay, only required if paying to a lightning address or the amount is not specified in the BOLT 11 invoice.
     * @param args additional options, e.g. to store metadata on the payment
     * @returns the receipt of the payment, and details of the paid invoice.
     */
    pay(recipient: string, amount?: Amount, args?: Omit<Nip47PayInvoiceRequest, "invoice" | "amount">): Promise<{
        invoice: Invoice;
        preimage: string;
        fees_paid: number;
    }>;
    /**
     * Request to receive a payment
     * @param amount the amount requested, either in sats (e.g. {satoshi: 21}) or fiat (e.g. new FiatAmount(21, "USD")).
     * @param args additional options, e.g. to set a description on the payment request, or store metadata for the received payment
     * @returns the invoice to be paid, along with methods to easily listen for a payment and act upon it.
     */
    requestPayment(amount: Amount, args?: Omit<Nip47MakeInvoiceRequest, "amount">): Promise<ReceiveInvoice>;
    close(): void;
}

declare class FiatAmount {
    satoshi: Promise<number>;
    constructor(amount: number, currency: string);
}
declare const USD: (amount: number) => FiatAmount;
declare const EUR: (amount: number) => FiatAmount;
declare const JPY: (amount: number) => FiatAmount;
declare const GBP: (amount: number) => FiatAmount;
declare const CHF: (amount: number) => FiatAmount;

export { CHF, EUR, FiatAmount, GBP, JPY, LNClient as LN, LNClient, ReceiveInvoice, SATS, USD, resolveAmount };
export type { Amount, LNClientCredentials };
